SELECT CASE WHEN budget >= 4059000 THEN 'high' WHEN budget >= 1822000 THEN 'mid' ELSE 'low' END AS budget_bucket, CASE WHEN location IN ('Chiang Mai', 'Singapore') THEN 'tier_1' ELSE 'other' END AS location_group, SUM(budget) AS total_budget, COUNT(DISTINCT budget) AS unique_dept_names, AVG(budget) AS avg_budget FROM departments WHERE budget <= 3281000 GROUP BY ROLLUP(CASE WHEN budget >= 4059000 THEN 'high' WHEN budget >= 1822000 THEN 'mid' ELSE 'low' END, CASE WHEN location IN ('Chiang Mai', 'Singapore') THEN 'tier_1' ELSE 'other' END) ORDER BY unique_dept_names
